import React, { createContext, useContext, useState, useEffect } from 'react';
import { DUMMY_USERS, DUMMY_RESOURCES } from '../data/dummyData';

const AppContext = createContext();

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

export const AppProvider = ({ children }) => {
  // State
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('landing');
  const [dark, setDark] = useState(false);
  const [selectedCollege, setSelectedCollege] = useState(null);
  const [resources, setResources] = useState(DUMMY_RESOURCES);
  const [users, setUsers] = useState(DUMMY_USERS);
  const [routineDone, setRoutineDone] = useState({});
  const [toasts, setToasts] = useState([]);

  // API base URL
  const API = 'http://localhost:5000/api';

  // Toast system
  const toast = (message, type = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => removeToast(id), 4000);
  };

  const removeToast = (id) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  // Auth functions
  const login = async (email, password) => {
    try {
      const res = await fetch(`${API}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();
      if (!res.ok) { toast(data.message, 'error'); return false; }

      localStorage.setItem('token', data.token);
      setUser(data.user);
      setPage('dashboard');
      toast(`Welcome back, ${data.user.name.split(' ')[0]}! 👋`);
      return true;
    } catch (err) {
      toast('Server error. Please try again.', 'error');
      return false;
    }
  };

  const register = async (formData) => {
    try {
      const res = await fetch(`${API}/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });
      const data = await res.json();
      if (!res.ok) { toast(data.message, 'error'); return false; }

      localStorage.setItem('token', data.token);
      setUser(data.user);
      setPage('dashboard');
      toast(`Welcome, ${data.user.name.split(' ')[0]}! 🎉`);
      return true;
    } catch (err) {
      toast('Server error. Please try again.', 'error');
      return false;
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
    setPage('landing');
    toast('Logged out successfully', 'success');
  };

  // Resource management
  const addResource = (resource) => {
    setResources(prev => [...prev, { ...resource, id: Date.now() }]);
    toast('Resource uploaded successfully!', 'success');
  };

  const removeUser = (userId) => {
    setUsers(prev => prev.filter(u => u.id !== userId));
    toast('User removed successfully', 'success');
  };

  // Initialize from localStorage
  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      // In a real app, you'd validate the token with the server
      // For now, we'll just check if it exists
      const savedUser = JSON.parse(localStorage.getItem('user'));
      if (savedUser) {
        setUser(savedUser);
        setPage('dashboard');
      }
    }

    // Check for dark mode preference
    const darkMode = localStorage.getItem('darkMode') === 'true';
    setDark(darkMode);
  }, []);

  // Save dark mode preference
  useEffect(() => {
    localStorage.setItem('darkMode', dark);
  }, [dark]);

  const value = {
    // State
    user,
    page,
    dark,
    selectedCollege,
    resources,
    users,
    routineDone,
    toasts,

    // Setters
    setUser,
    setPage,
    setDark,
    setSelectedCollege,
    setResources,
    setUsers,
    setRoutineDone,

    // Functions
    login,
    register,
    logout,
    toast,
    removeToast,
    addResource,
    removeUser,
  };

  return (
    <AppContext.Provider value={value}>
      {children}
    </AppContext.Provider>
  );
};
